<script setup>
import { computed, inject, ref } from 'vue';
import { useForm } from '@inertiajs/vue3';
import { formatMoney } from '@/Utils/format';
import Modal from '@/Components/UI/Modal.vue';
import BulkProductImport from './BulkProductImport.vue';
import { PlusIcon, PencilIcon, TrashIcon } from '@heroicons/vue/24/outline';
const props = defineProps({ trip: Object, breakdown: Object });
const emit = defineEmits(['delete']);
const route = inject('route');
const editingId = ref(null);
const adding = ref(false);
const detailId = ref(null);
const selected = computed(() => props.trip.products.find(p => p.id === detailId.value));
const selectedCost = computed(() => props.breakdown?.lines?.find(p => p.id === detailId.value));
const allocations = computed(() => props.breakdown?.allocations?.filter(a => a.product_id === detailId.value) || []);
const editable = computed(() => props.trip.estado === 'activo');
const form = useForm({ nombre: '', moneda: props.trip.moneda_trabajo, cantidad: 1, costo_unitario: '', weight: '', volume: '', expected_revision: props.trip.revision });
const edit = useForm({ nombre: '', moneda: '', cantidad: 1, costo_unitario: '', expected_revision: props.trip.revision });
const beginEdit = product => { editingId.value = product.id; edit.clearErrors(); Object.assign(edit, { nombre: product.nombre, moneda: product.moneda, cantidad: product.cantidad, costo_unitario: product.costo_unitario, expected_revision: props.trip.revision }); };
const cancel = () => { editingId.value = null; edit.clearErrors(); };
const save = product => edit.put(route('trips.products.update', [props.trip.id, product.id]), { preserveScroll: true, onSuccess: cancel });
const add = () => form.transform(data => ({ ...data, expected_revision: props.trip.revision })).post(route('trips.products.store', props.trip.id), { preserveScroll: true, onSuccess: () => { form.reset(); adding.value = false; } });
</script>
<template>
    <BulkProductImport v-if="editable" :trip="trip" />
    <section class="f-panel"><div class="f-panel-heading"><div><h2>Hoja de productos</h2><p class="f-hint">{{ trip.products.length }} líneas · revisión {{ trip.revision }} · totales guardados</p></div><button v-if="editable" class="f-button f-button-primary" @click="adding = !adding"><PlusIcon /> Agregar producto</button></div>
        <form v-if="adding" class="f-panel-body f-form-grid" @submit.prevent="add"><div class="f-field"><label for="product-name">Producto</label><input id="product-name" class="f-input" v-model="form.nombre" required maxlength="255" /><span class="f-field-error">{{ form.errors.nombre }}</span></div><div class="f-field"><label for="product-currency">Moneda original</label><select id="product-currency" class="f-input" v-model="form.moneda"><option :value="trip.moneda_trabajo">{{ trip.moneda_trabajo }}</option><option value="CLP">CLP</option></select></div><div class="f-field"><label for="product-quantity">Cantidad</label><input id="product-quantity" class="f-input" type="number" v-model="form.cantidad" min="1" max="1000000" step="1" required /><span class="f-field-error">{{ form.errors.cantidad }}</span></div><div class="f-field"><label for="product-cost">Costo unitario original · {{ form.moneda }}</label><input id="product-cost" class="f-input" type="number" v-model="form.costo_unitario" min="0" step="0.01" required /><span class="f-field-error">{{ form.errors.costo_unitario }}</span></div><div class="f-field"><label for="product-weight">Peso total de la línea · kg (opcional)</label><input id="product-weight" class="f-input" type="number" v-model="form.weight" min="0" step="0.00000001" /></div><div class="f-field"><label for="product-volume">Volumen total de la línea · m³ (opcional)</label><input id="product-volume" class="f-input" type="number" v-model="form.volume" min="0" step="0.00000001" /></div><p class="f-hint">El borrador no modifica los totales hasta que guardes.</p><div class="f-actions"><button type="button" class="f-button" @click="adding = false">Cancelar</button><button type="submit" class="f-button f-button-primary" :disabled="form.processing">{{ form.processing ? 'Guardando…' : 'Guardar producto' }}</button></div></form>
        <template v-if="trip.products.length">
            <div class="f-table-scroll f-desktop-table"><table class="f-table"><caption class="sr-only">Hoja editable de productos, costos guardados y trazabilidad</caption><thead><tr><th>Producto</th><th class="f-numeric">Unidades</th><th class="f-numeric">Unitario original</th><th class="f-numeric">Compra · CLP</th><th class="f-numeric">Gastos · CLP</th><th class="f-numeric">Costo unitario · CLP</th><th class="f-numeric">Total · CLP</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><tr v-for="product in trip.products" :key="product.id" @keydown.esc="cancel"><td><template v-if="editingId === product.id"><input class="f-input" v-model="edit.nombre" :aria-label="`Nombre de ${product.nombre}`" @keydown.enter.prevent="save(product)" /><select class="f-input" v-model="edit.moneda" aria-label="Moneda original"><option :value="trip.moneda_trabajo">{{ trip.moneda_trabajo }}</option><option value="CLP">CLP</option></select><span class="f-field-error">{{ edit.errors.nombre }}</span></template><template v-else><button class="f-table-title" @click="detailId = product.id">{{ product.nombre }}</button><span class="f-table-subtitle">{{ product.moneda }} · {{ product.rate_mode === 'paid' ? 'Tasa histórica de pago' : 'Tasa estimada' }}</span></template></td><td class="f-numeric"><input v-if="editingId === product.id" class="f-input" style="width:85px" v-model="edit.cantidad" type="number" min="1" :aria-label="`Cantidad de ${product.nombre}`" @keydown.enter.prevent="save(product)" /><template v-else>{{ product.cantidad }}</template></td><td class="f-numeric"><input v-if="editingId === product.id" class="f-input" style="width:115px" v-model="edit.costo_unitario" type="number" min="0" step="0.01" :aria-label="`Costo original de ${product.nombre}`" @keydown.enter.prevent="save(product)" /><template v-else>{{ formatMoney(product.costo_unitario, 2) }} {{ product.moneda }}</template></td><td class="f-numeric">${{ formatMoney(product.subtotal_clp) }}</td><td class="f-numeric">${{ formatMoney(product.gastos_prorrateados_clp) }}</td><td class="f-numeric"><button @click="detailId = product.id" style="text-decoration:underline;text-decoration-style:dotted">${{ formatMoney(product.costo_final_unitario_clp, 2) }}</button></td><td class="f-numeric"><strong>${{ formatMoney(product.costo_final_total_clp) }}</strong></td><td><div v-if="editable" class="f-actions"><template v-if="editingId === product.id"><button class="f-button f-button-primary" @click="save(product)" :disabled="edit.processing">Guardar</button><button class="f-button" @click="cancel">Cancelar</button></template><template v-else><button class="f-icon-button" @click="beginEdit(product)" :aria-label="`Editar ${product.nombre}`"><PencilIcon /></button><button class="f-icon-button" @click="emit('delete', product)" :aria-label="`Eliminar ${product.nombre}`"><TrashIcon /></button></template></div></td></tr></tbody></table></div>
            <div class="f-mobile-cards"><article v-for="product in trip.products" :key="product.id" class="f-mobile-card"><div class="f-mobile-card-top"><div><button class="f-table-title" @click="detailId = product.id">{{ product.nombre }}</button><span class="f-table-subtitle">{{ product.cantidad }} unidades · {{ formatMoney(product.costo_unitario, 2) }} {{ product.moneda }} / unidad</span></div><button v-if="editable" class="f-icon-button" @click="beginEdit(product)" :aria-label="`Editar ${product.nombre}`"><PencilIcon /></button></div><div v-if="editingId === product.id" class="f-form-grid f-draft" style="margin-top:16px"><div class="f-field"><label :for="`mobile-name-${product.id}`">Nombre</label><input :id="`mobile-name-${product.id}`" class="f-input" v-model="edit.nombre" /></div><div class="f-field"><label :for="`mobile-currency-${product.id}`">Moneda</label><select :id="`mobile-currency-${product.id}`" class="f-input" v-model="edit.moneda"><option :value="trip.moneda_trabajo">{{ trip.moneda_trabajo }}</option><option value="CLP">CLP</option></select></div><div class="f-field"><label :for="`mobile-quantity-${product.id}`">Cantidad</label><input :id="`mobile-quantity-${product.id}`" class="f-input" type="number" v-model="edit.cantidad" min="1" /></div><div class="f-field"><label :for="`mobile-cost-${product.id}`">Costo original</label><input :id="`mobile-cost-${product.id}`" class="f-input" type="number" v-model="edit.costo_unitario" min="0" step="0.01" /></div><p class="f-hint">Los totales siguen mostrando el costo guardado.</p><div class="f-actions"><button class="f-button" @click="cancel">Cancelar</button><button class="f-button f-button-primary" @click="save(product)" :disabled="edit.processing">Guardar</button><button class="f-button f-button-danger" @click="emit('delete',product)">Eliminar</button></div></div><div class="f-mobile-card-bottom"><span class="f-hint">Costo unitario final</span><button @click="detailId = product.id"><strong>${{ formatMoney(product.costo_final_unitario_clp, 2) }}</strong></button></div><div class="f-mobile-card-bottom" style="margin-top:8px"><span class="f-hint">Total de la línea · CLP</span><strong>${{ formatMoney(product.costo_final_total_clp) }}</strong></div></article></div>
        </template><div v-else class="f-empty"><h2>Aún no hay productos</h2><p>Agrega la compra en su moneda original. Los gastos se distribuirán al guardar.</p><button v-if="editable" class="f-button f-button-primary" @click="adding = true">Agregar primer producto</button></div>
    </section>
    <p class="f-footer-note">Enter guarda la fila en edición. Escape cancela el borrador. Selecciona cualquier costo unitario para ver su desglose. Los gastos se reparten al peso y los residuos se asignan por orden estable.</p>
    <Modal :show="!!selected" @close="detailId = null" :title="selected ? `Costo de ${selected.nombre}` : 'Desglose de costo'"><template v-if="selected"><div class="f-breakdown-row"><span>Compra convertida</span><strong>${{ formatMoney(selectedCost?.purchase ?? selected.subtotal_clp) }}</strong></div><div class="f-breakdown-row"><span>Gastos asignados</span><strong>${{ formatMoney(selectedCost?.assigned ?? selected.gastos_prorrateados_clp) }}</strong></div><div class="f-breakdown-row"><span>Total de {{ selected.cantidad }} unidades</span><strong>${{ formatMoney(selectedCost?.total ?? selected.costo_final_total_clp) }}</strong></div><div class="f-breakdown-row"><span>Costo por unidad · CLP</span><strong>${{ formatMoney(selectedCost?.unit_cost ?? selected.costo_final_unitario_clp,2) }}</strong></div><p class="f-hint" style="margin-top:12px">Tasa {{ selected.rate_mode === 'paid' ? 'histórica' : 'estimada' }}: {{ selected.moneda === 'CLP' ? '1' : selected.rate_mode === 'paid' ? selected.applied_rate : trip.tipo_cambio }} CLP / {{ selected.moneda }} · revisión {{ trip.revision }}</p><div v-for="allocation in allocations" :key="allocation.expense_id" class="f-breakdown-row"><span>{{ trip.expenses.find(e => e.id === allocation.expense_id)?.concepto }} <small class="f-hint">· {{ allocation.method }}</small></span><strong>${{ formatMoney(allocation.amount) }}</strong></div><p v-if="!breakdown" class="f-hint" style="margin-top:15px">Datos heredados: aún no existe una ejecución de costo verificable para este lote.</p></template></Modal>
</template>
